const countdown = {
  from: 3,
  to: 1,
  // implement Symbol.iterator
};

console.log([...countdown]);
console.log([...countdown]);

questions.answer:
const countdown = {
  from: 3,
  to: 1,
  [Symbol.iterator]() {
    let current = this.from;
    const last = this.to;
    return {
      next() {
        return current >= last
          ? { value: current--, done: false }
          : { value: undefined, done: true };
      },
    };
  },
};

console.log([...countdown]);
console.log([...countdown]);

