questions.answer:
function take(iterable, count) {
  const result = [];
  const iterator = iterable[Symbol.iterator]();

  while (result.length < count) {
    const { value, done } = iterator.next();
    if (done) break;
    result.push(value);
  }

  return result;
}

function* naturals() {
  let n = 1;
  while (true) yield n++;
}

console.log(take(naturals(), 4));

